   205	function goBack(fallbackRoute?: Route, shouldEnforceFallback = false, shouldPopToTop = false) {
   206	    if (!canNavigate('goBack')) {
   207	        return;
   208	    }
   209	
   210	    if (shouldPopToTop) {
   211	        if (shouldPopAllStateOnUP) {
   212	            shouldPopAllStateOnUP = false;
   213	            navigationRef.current?.dispatch(StackActions.popToTop());
   214	            return;
   215	        }
   216	    }
   217	
   218	    if (!navigationRef.current?.canGoBack()) {
   219	        Log.hmmm('[Navigation] Unable to go back');
   220	        return;
   221	    }
   222	
   223	    const isFirstRouteInNavigator = !getActiveRouteIndex(navigationRef.current.getState());
   224	    if (isFirstRouteInNavigator) {
   225	        const rootState = navigationRef.getRootState();
   226	        const lastRoute = rootState.routes.at(-1);
   227	        // If the user comes from a different flow (there is more than one route in ModalNavigator) we should go back to the previous flow on UP button press instead of using the fallbackRoute.
   228	        if ((lastRoute?.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR || lastRoute?.name === NAVIGATORS.LEFT_MODAL_NAVIGATOR) && (lastRoute.state?.index ?? 0) > 0) {
   229	            navigationRef.current.goBack();
   230	            return;
   231	        }
   232	    }
