   240	    const distanceFromPathInRootNavigator = getDistanceFromPathInRootNavigator(fallbackRoute ?? '');
   241	
   242	    if (isCentralPaneFocused && fallbackRoute) {
   243	        // Allow CentralPane to use UP with fallback route if the path is not found in root navigator.
   244	        if (distanceFromPathInRootNavigator === -1) {
   245	            navigate(fallbackRoute, CONST.NAVIGATION.TYPE.UP);
   246	            return;
   247	        }
   248	
   249	        // Add possibility to go back more than one screen in root navigator if that screen is on the stack.
   250	        if (distanceFromPathInRootNavigator > 0) {
   251	            navigationRef.current.dispatch(StackActions.pop(distanceFromPathInRootNavigator));
   252	            return;
   253	        }
   254	    }
   255	
   256	    // If the central pane is focused, it's possible that we navigated from other central pane with different matching bottom tab.
   257	    if (isCentralPaneFocused) {
   258	        const rootState = navigationRef.getRootState();
