   260	        const topmostCentralPaneRouteAfterPop = getTopmostCentralPaneRoute(stateAfterPop);
   261	
   262	        const topmostBottomTabRoute = getTopmostBottomTabRoute(rootState as State<RootStackParamList>);
   263	        const matchingBottomTabRoute = getMatchingBottomTabRouteForState(stateAfterPop);
   264	
   265	        // If the central pane is defined after the pop action, we need to check if it's synced with the bottom tab screen.
   266	        // If not, we need to pop to the bottom tab screen/screens to sync it with the new central pane.
   267	        if (topmostCentralPaneRouteAfterPop && topmostBottomTabRoute?.name !== matchingBottomTabRoute.name) {
