   269	
   270	            if (bottomTabNavigator && bottomTabNavigator.index) {
   271	                const matchingIndex = bottomTabNavigator.routes.findLastIndex((item) => item.name === matchingBottomTabRoute.name);
   272	                const indexToPop = matchingIndex !== -1 ? bottomTabNavigator.index - matchingIndex : undefined;
   273	                navigationRef.current.dispatch({...StackActions.pop(indexToPop), target: bottomTabNavigator?.key});
   274	            }
   275	        }
   276	    }
