function isValidURL(url: string): boolean {
    if (!/^(https?|ftp):\/\//i.test(url)) {
        return false;
    }

    try {
        const parsedURL = new URL(url);
        const validDomains = ['new.expensify.com', 'staging.new.expensify.com', 'dev.new.expensify.com'];
        if (!validDomains.includes(parsedURL.hostname)) {
            return false;
        }

        const validPaths = [
            /^\/r\/\d+$/, 
            /^\/r$/, 
            /^\/settings$/, 
        ];
        if (!validPaths.some(path => path.test(parsedURL.pathname))) {
            return false;
        }
    } catch (e) {
        return false;
    }

    return true;
}

